llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C22"],
      "claim": "Methoxsalen, a furanocoumarin sharing the coumarin lactone core, has relatively low systemic bioavailability in humans; this is the closest structural analogue and supports low oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Chrysin has a measured oral bioavailability of only 0.003–0.02% in humans, far below the 20% threshold, indicating that related oxygen-heterocyclic natural products can undergo extensive first-pass metabolism and poor systemic exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Baicalein is reported to have low oral bioavailability in humans, providing additional support that polyphenolic chromone-type molecules are poorly systemically available after oral dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Anthocyanins have oral bioavailability estimated at less than 1–2% in humans, reinforcing the pattern of very low systemic availability among related oxygen-containing heterocyclic flavonoids.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Cromolyn has less than 1% systemic bioavailability after oral administration in humans, showing that even approved drugs with heterocyclic structures can fall far below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Zonisamide has virtually complete oral bioavailability in humans, but it is structurally distant from the coumarin query and its high absorption does not transfer strongly to this lactone scaffold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C02"],
      "claim": "Oxaprozin has high systemic availability in humans, but its carboxylic acid and oxazole structure is not closely related to the coumarin core, limiting transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest structural analogue, methoxsalen, shows low systemic bioavailability in humans, and multiple related oxygen-heterocyclic compounds (chrysin, baicalein, anthocyanins, cromolyn) have very low oral bioavailability. The query coumarin is a small lipophilic lactone expected to undergo extensive first-pass metabolism, so the affirmative low-bioavailability evidence outweighs the distant high-bioavailability drugs. Prediction: low (F < 20%).",
  "evidence_gaps": [
    "No direct human absolute oral bioavailability measurement for coumarin itself is present in the supplied evidence.",
    "All retrieved analogues have low Morgan similarity (<0.32), limiting quantitative transferability.",
    "First-pass metabolism and species differences are inferred rather than directly measured for the query molecule."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

